//! OAuth callback infrastructure used by the NEAR AI session login flow.//!//! These utilities (callback server, landing pages, hostname detection) were//! originally in `cli/oauth_defaults.rs` and are moved here so the `llm`//! module is self-contained. `cli/oauth_defaults` re-exports everything for//! backward compatibility.use std::collections::HashMap;use std::time::Duration;use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};use tokio::net::TcpListener;/// Fixed port for the OAuth callback listener.pub const OAUTH_CALLBACK_PORT: u16 = 9876;/// Error from the OAuth callback listener.#[derive(Debug, thiserror::Error)]pub enum OAuthCallbackError {    #[error("Port {0} is in use (another auth flow running?): {1}")]    PortInUse(u16, String),    #[error("Authorization denied by user")]    Denied,    #[error("Timed out waiting for authorization")]    Timeout,    #[error("CSRF state mismatch: expected {expected}, got {actual}")]    StateMismatch { expected: String, actual: String },    #[error("IO error: {0}")]    Io(String),}/// Returns the OAuth callback base URL.////// Checks `IRONCLAW_OAUTH_CALLBACK_URL` env var first (useful for remote/VPS/// deployments where `127.0.0.1` is unreachable from the user's browser),/// then falls back to `http://{callback_host()}:{OAUTH_CALLBACK_PORT}`.pub fn callback_url() -> String {    std::env::var("IRONCLAW_OAUTH_CALLBACK_URL")        .ok()        .filter(|v| !v.is_empty())        .unwrap_or_else(|| format!("http://{}:{}", callback_host(), OAUTH_CALLBACK_PORT))}/// Returns the hostname used in OAuth callback URLs.////// Reads `OAUTH_CALLBACK_HOST` from the environment (default: `127.0.0.1`).////// **Remote server usage:** set `OAUTH_CALLBACK_HOST` to the specific network/// interface address you want to listen on (e.g. the server's LAN IP)./// Wildcard addresses (`0.0.0.0`, `::`) are rejected — use a specific interface/// IP to limit exposure. The callback listener will bind to that address so the/// OAuth redirect can reach an external browser./// Note: this transmits the session token over plain HTTP — prefer SSH port/// forwarding (`ssh -L 9876:127.0.0.1:9876 user@host`) when possible.pub fn callback_host() -> String {    std::env::var("OAUTH_CALLBACK_HOST").unwrap_or_else(|_| "127.0.0.1".to_string())}/// Returns `true` if `host` is a loopback address that only accepts local connections.////// Covers `localhost` (case-insensitive), the full `127.0.0.0/8` IPv4 loopback/// range, and `::1` for IPv6.pub fn is_loopback_host(host: &str) -> bool {    if host.eq_ignore_ascii_case("localhost") {        return true;    }    host.parse::<std::net::IpAddr>()        .map(|ip| ip.is_loopback())        .unwrap_or(false)}/// Returns `true` if `host` is a wildcard/unspecified address (`0.0.0.0` or `::`).////// Wildcard binds accept connections on all interfaces, which is a security risk/// for OAuth callbacks that carry session tokens over plain HTTP.fn is_wildcard_host(host: &str) -> bool {    host.parse::<std::net::IpAddr>()        .map(|ip| ip.is_unspecified())        .unwrap_or(false)}/// Map a `std::io::Error` from a bind attempt to an `OAuthCallbackError`.fn bind_error(e: std::io::Error) -> OAuthCallbackError {    if e.kind() == std::io::ErrorKind::AddrInUse {        OAuthCallbackError::PortInUse(OAUTH_CALLBACK_PORT, e.to_string())    } else {        OAuthCallbackError::Io(e.to_string())    }}/// Bind the OAuth callback listener on the fixed port.////// When `OAUTH_CALLBACK_HOST` is a loopback address (the default `127.0.0.1`),/// binds to `127.0.0.1` first and falls back to `[::1]` so local-only auth/// flows remain restricted to the local machine.////// When `OAUTH_CALLBACK_HOST` is set to a remote address, binds to that/// specific address so only connections directed to it are accepted.pub async fn bind_callback_listener() -> Result<TcpListener, OAuthCallbackError> {    let host = callback_host();    if is_wildcard_host(&host) {        return Err(OAuthCallbackError::Io(format!(            "OAUTH_CALLBACK_HOST={host} is a wildcard address — this would accept \             connections on all interfaces, exposing the session token. \             Use a specific interface IP (e.g. 192.168.1.x) or SSH port forwarding instead."        )));    }    if is_loopback_host(&host) {        // Local mode: prefer IPv4 loopback, fall back to IPv6.        let ipv4_addr = format!("127.0.0.1:{}", OAUTH_CALLBACK_PORT);        match TcpListener::bind(&ipv4_addr).await {            Ok(listener) => return Ok(listener),            Err(e) if e.kind() == std::io::ErrorKind::AddrInUse => {                return Err(OAuthCallbackError::PortInUse(                    OAUTH_CALLBACK_PORT,                    e.to_string(),                ));            }            Err(_) => {                // IPv4 not available, fall back to IPv6            }        }        TcpListener::bind(format!("[::1]:{}", OAUTH_CALLBACK_PORT))            .await            .map_err(bind_error)    } else {        // Remote mode: bind to the specific configured host address only,        // not 0.0.0.0, to limit exposure to the intended interface.        let addr = format!("{}:{}", host, OAUTH_CALLBACK_PORT);        TcpListener::bind(&addr).await.map_err(bind_error)    }}/// Wait for an OAuth callback and extract a query parameter value.////// Listens for a GET request matching `path_prefix` (e.g., "/callback" or "/auth/callback"),/// extracts the value of `param_name` (e.g., "code" or "token"), and shows a branded/// landing page using `display_name` (e.g., "Google", "Notion", "NEAR AI").////// When `expected_state` is `Some`, the callback's `state` query parameter is validated/// against it to prevent CSRF attacks. If the state doesn't match, the callback is/// rejected with an error page.////// Times out after 5 minutes.